📱 Improve mobile responsiveness of conference rail ()
Files: docs/en/docs/css/custom.css, docs/en/overrides/main.html, docs/en/overrides/partials/conf-rail.html
Symbols: 
--- docs/en/docs/css/custom.css
+++ docs/en/docs/css/custom.css
@@ -510 +510,28 @@ Inspired by Termynal's CSS tricks with modifications
-.md-sidebar--primary:has(.fastapi-conf-rail) { position: static; }
+.fastapi-conf-rail--mobile {
+  display: none;
+}
+
+@media screen and (max-width: 76.234375em) {
+  .fastapi-conf-rail:not(.fastapi-conf-rail--mobile) {
+    display: none;
+  }
+
+  .md-typeset .fastapi-conf-rail--mobile {
+    display: grid;
+    grid-template-columns: minmax(0, 1fr) auto;
+    margin: 0 0 1.25rem;
+    text-decoration: none;
+  }
+
+  .fastapi-conf-rail--mobile .fastapi-conf-rail__summary {
+    display: none;
+  }
+
+  .fastapi-conf-rail--mobile .fastapi-conf-rail__cta {
+    grid-column: 2;
+    grid-row: 1 / 4;
+    align-self: center;
+    margin: 0 0 0 0.8rem;
